// Buffer top-up (Part 2 §2.4): prefer the earliest planned fb_content_plan slot within
// GENERATION_BUFFER_DAYS that has no post yet; otherwise fall back to the first open date
// in a 5-day window so it never goes dark. Reads fb_content_plan (incl. any Strategist brief)
// + the chosen subtopic via httpRequest. The on-demand (fb-generate-now) path skips this node.
const taken = new Set($('Get Existing Dates').all().map(i => i.json && i.json.scheduled_date).filter(Boolean));
const SB = '__SUPABASE_URL__';
const KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
const h = { apikey: KEY, Authorization: 'Bearer ' + KEY };
const buffer = Number($env.GENERATION_BUFFER_DAYS || 7);
const today = $now.toFormat('yyyy-LL-dd');
const until = $now.plus({ days: buffer }).toFormat('yyyy-LL-dd');
const planned = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_content_plan?status=eq.planned&plan_date=gte.' + today + '&plan_date=lte.' + until + '&select=id,plan_date,pillar,archetype,subtopic_id,brief,brief_status&order=plan_date.asc', headers: h, json: true });
const slot = (planned || []).find(s => !taken.has(s.plan_date));
if (slot) {
  let subtopic = null;
  if (slot.subtopic_id) {
    const rows = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_subtopics?id=eq.' + slot.subtopic_id + '&select=id,subtopic,pillar,times_used', headers: h, json: true });
    subtopic = (rows && rows[0]) || null;
  }
  return [{ json: { scheduled_date: slot.plan_date, follow_plan: true, plan_id: slot.id, plan_pillar: slot.pillar, plan_archetype: slot.archetype, plan_subtopic_id: slot.subtopic_id || null, subtopic, brief: slot.brief || null, brief_status: slot.brief_status || 'none' } }];
}
// Fallback: first open date within a 5-day horizon (original behaviour).
let target = null;
for (let i = 0; i < 5; i++) { const iso = $now.plus({ days: i }).toFormat('yyyy-LL-dd'); if (!taken.has(iso)) { target = iso; break; } }
if (!target) return [];               // horizon full -> emit nothing (no-op night)
return [{ json: { scheduled_date: target, follow_plan: false, plan_id: null } }];

// Merge subtopic + prompts + message bank into the generator system/user prompts.
// Prefer the planned slot's pillar/archetype/subtopic (nightly buffer top-up); otherwise the
// least-recently-used active subtopic + a date-derived archetype (also the on-demand path).
// Returns { system, user, subtopic_id, pillar, times_used, archetype, scheduled_date, plan_id,
// media_type, video_concept, visual_angle, image_template }. media_type may be text
// (no image): webhook override > brief format > text_share date rotation.
let picked = null; try { picked = $('Pick Plan Slot or Date').first().json; } catch (e) {}
const lru = $('Get LRU Subtopic').first().json;
const followPlan = !!(picked && picked.follow_plan);
const sub = (followPlan && picked.subtopic) ? picked.subtopic : lru;
const promptItems = $('Get Prompts + Bank').all();
const byName = Object.fromEntries(promptItems.map(i => [i.json.name, i.json.body]));
const bank = $('Get Message Bank').first()?.json?.variables ?? {};

const archetypes = ['myth-bust','secret-reveal','story','mistake-expose','seasonal','thought-leadership','community-cause','social-proof'];
const pillar = (followPlan && picked.plan_pillar) ? picked.plan_pillar : (sub.pillar || '');
const archetype = (followPlan && picked.plan_archetype) ? picked.plan_archetype : archetypes[new Date().getDate() % archetypes.length];

// Strategist brief (only when the plan slot carries an APPROVED brief); else image-only
// fallbacks. Media type is the brief's decision: video when the brief supplies a video_concept
// or a reel/video/motion format, else image (also the on-demand + no-brief path).
const brief = (followPlan && picked && picked.brief_status === 'approved' && picked.brief) ? picked.brief : null;
const pillarFinal = (brief && brief.pillar) ? brief.pillar : pillar;
const buyerStage = (brief && brief.funnel_stage) ? brief.funnel_stage : '#1';
const buyerObjective = (brief && brief.buyer_objective) ? brief.buyer_objective : 'education';
const captionDirection = (brief && brief.caption_direction) ? brief.caption_direction : '';
const recommendedCta = (brief && brief.recommended_cta) ? brief.recommended_cta : 'soft: end with one engagement question';
const imageConcept = (brief && brief.image_concept) ? brief.image_concept : '';
const recFmt = (brief && brief.recommended_format) ? String(brief.recommended_format) : '';
const videoConcept = (brief && brief.video_concept) ? brief.video_concept : '';
let mediaType = (brief && (videoConcept || /reel|video|motion/i.test(recFmt))) ? 'video' : (brief && /text/i.test(recFmt)) ? 'text' : 'image';

// scheduled_date comes from the webhook body (on-demand) or the picker (nightly).
let scheduled_date = null;
try { scheduled_date = $('On-demand (fb-generate-now)').first().json.body.scheduled_date; } catch (e) {}
if (!scheduled_date) { try { scheduled_date = picked.scheduled_date; } catch (e) {} }

// On-demand dedupe guard: if a post for this date was created in the last 3 minutes, a
// double-click or an error-page retry already generated it — end quietly (the webhook has
// already answered {queued:true}). A second insert-time guard (keyed to run_started)
// catches the race where the retry starts BEFORE the first run's insert lands.
let onDemand = false;
try { onDemand = !!$('On-demand (fb-generate-now)').first(); } catch (e) {}
if (onDemand && scheduled_date) {
  let dupRows = [];
  try { dupRows = await this.helpers.httpRequest({ method: 'GET', url: '__SUPABASE_URL__' + '/rest/v1/fb_posts?scheduled_date=eq.' + scheduled_date + '&created_at=gte.' + encodeURIComponent(new Date(Date.now() - 3 * 60000).toISOString()) + '&select=id', headers: { apikey: 'YOUR_SUPABASE_SERVICE_ROLE_KEY', Authorization: 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY' }, json: true }); } catch (e) {}
  if (dupRows && dupRows.length) return [];
}

// Visual variety: rotate the scene type by scheduled date, and remember recent image
// concepts so the image stage can steer away from repeating the same scene.
const VISUAL_ANGLES = [
  'extreme close-up of impact-glass or frame hardware detail — product macro, no people',
  'a beautiful Florida home exterior with new impact windows — curb appeal, golden-hour light',
  'a bright, light-filled interior room seen through large impact windows',
  'a happy homeowner or family moment at home — relaxed, confident, smiling',
  'an installer or craftsman fitting a window — skilled hands, pride in the work',
  'a dramatic storm sky over a Florida neighborhood — homes standing strong, no people',
  'a coastal Florida scene — palms, water, homes built for the climate',
  'macro of rain streaming down impact glass while the interior beyond stays warm and dry'
];
const angleDay = scheduled_date ? Math.floor(Date.parse(scheduled_date + 'T12:00:00Z') / 86400000) : Math.floor(Date.now() / 86400000);
const visual_angle = VISUAL_ANGLES[angleDay % VISUAL_ANGLES.length];
let recentRows = [];
try { recentRows = await this.helpers.httpRequest({ method: 'GET', url: '__SUPABASE_URL__' + '/rest/v1/fb_posts?select=image_concept&image_concept=not.is.null&order=created_at.desc&limit=8', headers: { apikey: 'YOUR_SUPABASE_SERVICE_ROLE_KEY', Authorization: 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY' }, json: true }); } catch (e) {}
const recent_scenes = (recentRows || []).map(r => String(r.image_concept || '').slice(0, 140)).filter(Boolean).join(' ; ') || 'none yet';

// Text-only mix: the webhook body's media_type wins (manual Dashboard path); else an
// approved brief that calls for text; else fb_settings.text_share (percent, null -> 25)
// drives a deterministic date rotation so roughly 1-in-N scheduled dates ship text-only.
let mediaReq = null;
try { mediaReq = $('On-demand (fb-generate-now)').first().json.body.media_type; } catch (e) {}
let text_share = 25;
try { const ts = await this.helpers.httpRequest({ method: 'GET', url: '__SUPABASE_URL__' + '/rest/v1/fb_settings?id=eq.1&select=text_share', headers: { apikey: 'YOUR_SUPABASE_SERVICE_ROLE_KEY', Authorization: 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY' }, json: true }); if (ts && ts[0] && ts[0].text_share !== null && ts[0].text_share !== undefined) text_share = ts[0].text_share; } catch (e) {}
if (mediaReq === 'text' || mediaReq === 'image') { mediaType = mediaReq; }
else if (mediaType === 'image' && text_share > 0 && (angleDay % Math.max(2, Math.round(100 / text_share)) === 0)) { mediaType = 'text'; }

// Image template: resolve everything except {{image_concept}}/{{post_body}} — the image
// node fills those in after the generator returns them. Feedback only applies in WF3 (regen).
const image_template = (byName['image'] || '')
  .replaceAll('{{visual_angle}}', visual_angle)
  .replaceAll('{{recent_scenes}}', recent_scenes)
  .replaceAll('{{image_feedback}}', 'none');

const user = (byName['generator'] || '')
  .replaceAll('{{style_guide}}', byName['style_guide'] || '')
  .replaceAll('{{message_bank}}', JSON.stringify(bank))
  .replaceAll('{{pillar}}', pillarFinal)
  .replaceAll('{{archetype}}', archetype)
  .replaceAll('{{subtopic}}', sub.subtopic || '')
  // generator v2 brief placeholders: use an approved Strategist brief when present, else the
  // no-brief defaults; then strip any leftover token so a literal one never ships.
  .replaceAll('{{buyer_stage}}', buyerStage)
  .replaceAll('{{buyer_objective}}', buyerObjective)
  .replaceAll('{{caption_direction}}', captionDirection)
  .replaceAll('{{media_type}}', mediaType)
  .replaceAll('{{image_concept}}', imageConcept)
  .replaceAll('{{video_concept}}', videoConcept)
  .replaceAll('{{recommended_cta}}', recommendedCta)
  .replaceAll('{{visual_angle}}', visual_angle)
  .replace(/\{\{[^}]+\}\}/g, '');


return [{ json: {
  system: byName['style_guide'] || '',
  user,
  subtopic_id: sub.id,
  pillar: pillarFinal,
  times_used: sub.times_used || 0,
  archetype,
  scheduled_date,
  plan_id: followPlan ? picked.plan_id : null,
  media_type: mediaType,
  video_concept: videoConcept,
  visual_angle,
  image_template,
  run_started: new Date(Date.now() - 15000).toISOString()
} }];

// Tolerant JSON parse: strip ```json fences, then JSON.parse; on failure extract
// the first balanced {...}. Returns the generator object { post_body, first_comment, image_concept, video_concept, ... }.
let t = $json.content?.[0]?.text || '';
t = t.replace(/```json|```/g, '').trim();
let out;
try { out = JSON.parse(t); } catch (e) {
  const m = t.match(/\{[\s\S]*\}/); out = m ? JSON.parse(m[0]) : {};
}
return [{ json: out }];

// Decode the base64 image returned by the provider and prepare it as binary for upload.
const b64 = $json.data?.[0]?.b64_json;
if (!b64) throw new Error('No image returned');
const path = `${$now.toFormat('yyyy-LL-dd')}-${Math.random().toString(36).slice(2,10)}.png`;
return [{ json: { path }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), path, 'image/png') } }];

// Public read URL for the uploaded image (note the /public/ segment).
// Insert-time dedupe (on-demand only): if another run inserted a post for this date after
// THIS run started (double-click / error-page retry race), emit nothing so the Insert node
// never fires. The orphaned storage upload is harmless.
const bgp = $('Build Generator Prompt').first().json;
let onDemand = false;
try { onDemand = !!$('On-demand (fb-generate-now)').first(); } catch (e) {}
if (onDemand && bgp.run_started) {
  let dupRows = [];
  try { dupRows = await this.helpers.httpRequest({ method: 'GET', url: '__SUPABASE_URL__' + '/rest/v1/fb_posts?scheduled_date=eq.' + bgp.scheduled_date + '&created_at=gte.' + encodeURIComponent(bgp.run_started) + '&select=id', headers: { apikey: 'YOUR_SUPABASE_SERVICE_ROLE_KEY', Authorization: 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY' }, json: true }); } catch (e) {}
  if (dupRows && dupRows.length) return [];
}
return [{ json: { image_url: `__SUPABASE_URL__/storage/v1/object/public/fb-images/${$('Decode Image').first().json.path}` } }];

// Animate the approved seed image into a 9:16 clip via fal (Veo 3.1 image-to-video by
// default, swappable). Submit -> poll (status_url) -> fetch result (response_url) -> download
// the MP4, returned as binary for the Upload node. Throws (surfaced in the n8n execution log,
// no post inserted) when FAL_KEY is unset or the job fails/times out. Model resolves from
// $env.FAL_ANIMATE_MODEL, else fb_settings.animate_still_model, else the veo3.1/fast default.
const FAL_KEY = $env.FAL_KEY;
if (!FAL_KEY) throw new Error('FAL_KEY is not set on this n8n instance');
const SB = '__SUPABASE_URL__';
const KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
let model = $env.FAL_ANIMATE_MODEL || '';
if (!model) {
  try {
    const rows = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_settings?id=eq.1&select=animate_still_model', headers: { apikey: KEY, Authorization: 'Bearer ' + KEY }, json: true });
    model = (rows && rows[0] && rows[0].animate_still_model) || '';
  } catch (e) {}
}
if (!model) model = 'fal-ai/veo3.1/fast/image-to-video';
const imageUrl = $('Set image_url').first().json.image_url;
const prompt = $('Parse JSON (tolerant)').first().json.video_concept || $('Build Generator Prompt').first().json.video_concept || 'Subtle, brand-safe motion: soft light shift and a slow push-in. No text, no logos.';
const fh = { Authorization: 'Key ' + FAL_KEY, 'Content-Type': 'application/json' };
const sub = await this.helpers.httpRequest({ method: 'POST', url: 'https://queue.fal.run/' + model, headers: fh, body: { prompt, image_url: imageUrl, aspect_ratio: '9:16', duration: '8s', resolution: '720p', generate_audio: false }, json: true });
if (!sub || !sub.status_url) throw new Error('fal submit failed: ' + JSON.stringify(sub));
let out = null;
for (let i = 0; i < 60; i++) {
  await new Promise(r => setTimeout(r, 5000));
  const st = await this.helpers.httpRequest({ method: 'GET', url: sub.status_url, headers: fh, json: true });
  const s = st && st.status;
  if (s === 'COMPLETED') { out = await this.helpers.httpRequest({ method: 'GET', url: sub.response_url, headers: fh, json: true }); break; }
  if (s === 'FAILED' || s === 'ERROR') throw new Error('fal video job failed: ' + JSON.stringify(st));
}
if (!out) throw new Error('fal video timed out after ~5 min');
const vurl = out.video && out.video.url;
if (!vurl) throw new Error('fal returned no video.url: ' + JSON.stringify(out));
const path = `${$now.toFormat('yyyy-LL-dd')}-${Math.random().toString(36).slice(2,10)}.mp4`;
const bin = await this.helpers.httpRequest({ method: 'GET', url: vurl, encoding: 'arraybuffer', returnFullResponse: false });
return [{ json: { path, video_url: SB + '/storage/v1/object/public/fb-videos/' + path }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(bin), path, 'video/mp4') } }];

// Insert-time dedupe (on-demand only): if another run inserted a post for this date after
// THIS run started (double-click / error-page retry race), emit nothing so the text Insert
// never fires.
const bgp = $('Build Generator Prompt').first().json;
let onDemand = false;
try { onDemand = !!$('On-demand (fb-generate-now)').first(); } catch (e) {}
if (onDemand && bgp.run_started) {
  let dupRows = [];
  try { dupRows = await this.helpers.httpRequest({ method: 'GET', url: '__SUPABASE_URL__' + '/rest/v1/fb_posts?scheduled_date=eq.' + bgp.scheduled_date + '&created_at=gte.' + encodeURIComponent(bgp.run_started) + '&select=id', headers: { apikey: 'YOUR_SUPABASE_SERVICE_ROLE_KEY', Authorization: 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY' }, json: true }); } catch (e) {}
  if (dupRows && dupRows.length) return [];
}
return $input.all();
